export const NAV_CSS = "/*\n * Al Ummah Now navigation contract (docs/design/NAV.md): the header account button, the account\n * menu and every menu that opens from the header, in every app (videos web, videos admin, www,\n * CMS, profile, auth admin). Framework-free: plain class names, any markup that follows NAV.md.\n *\n * Fanous tokens only. Every app vendors this file at a pinned commit (each repo's sync script);\n * fallbacks equal the token values so an app that vendors only the colour tokens still renders the\n * same sizes. Logical properties only, so it mirrors in RTL with no extra rules.\n *\n * The header is dark in every theme and mode: header controls use the nav tokens. A menu is not\n * part of the header: in light mode it is the page background with the page's text, in dark mode\n * the theme's menu tokens; it resets text colours, so it never inherits the header's light text.\n */\n\n/* ---------- header controls (on the dark header) ---------- */\n.aun-acct-btn,\n.aun-icon-btn,\n.aun-lang {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: var(--fanous-spacing-sm, 8px);\n  min-height: 2.5rem;\n  min-width: 2.5rem;\n  margin: 0;\n  padding-block: 0;\n  padding-inline: var(--fanous-spacing-sm, 8px);\n  border: 1px solid var(--fanous-c-nav-search-border);\n  border-radius: var(--fanous-radius-full, 999px);\n  background: transparent;\n  color: var(--fanous-c-nav-text);\n  font: inherit;\n  font-size: 0.9375rem;\n  font-weight: 500;\n  line-height: 1.2;\n  text-decoration: none;\n  cursor: pointer;\n  -webkit-tap-highlight-color: transparent;\n}\n.aun-icon-btn {\n  padding-inline: 0;\n}\n.aun-acct-btn {\n  max-width: 15rem;\n  padding-inline: var(--fanous-spacing-xs, 4px) var(--fanous-spacing-sm, 8px);\n}\n.aun-acct-btn:hover,\n.aun-icon-btn:hover,\n.aun-lang:hover,\n.aun-acct-btn[aria-expanded='true'],\n.aun-icon-btn[aria-expanded='true'] {\n  background: var(--fanous-c-nav-hover);\n}\n.aun-acct-btn:focus-visible,\n.aun-icon-btn:focus-visible,\n.aun-lang:focus-visible {\n  outline: 2px solid var(--fanous-c-nav-active-text);\n  outline-offset: 2px;\n}\n.aun-acct-btn svg,\n.aun-icon-btn svg {\n  width: 1.125rem;\n  height: 1.125rem;\n  flex: none;\n}\n.aun-acct-btn .aun-caret {\n  width: 0.875rem;\n  height: 0.875rem;\n  color: var(--fanous-c-nav-icon);\n}\n.aun-acct-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* phone: the button is the avatar and the caret; the name is still its accessible name */\n@media (max-width: 30rem) {\n  .aun-acct-btn .aun-acct-name {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    overflow: hidden;\n    clip-path: inset(50%);\n    white-space: nowrap;\n  }\n}\n\n/* ---------- avatar (image, else the name's first letter) ---------- */\n.aun-avatar {\n  display: inline-grid;\n  place-items: center;\n  flex: none;\n  width: 1.75rem;\n  height: 1.75rem;\n  border-radius: var(--fanous-radius-full, 999px);\n  overflow: hidden;\n  background: var(--fanous-color-primary);\n  color: var(--fanous-color-on-primary);\n  font-size: 0.8125rem;\n  font-weight: 700;\n  line-height: 1;\n  object-fit: cover;\n  text-transform: uppercase;\n}\n.aun-avatar img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n.aun-avatar--sm {\n  width: 1.5rem;\n  height: 1.5rem;\n  font-size: 0.75rem;\n}\n.aun-avatar--lg {\n  width: 2.5rem;\n  height: 2.5rem;\n  font-size: 1rem;\n}\n\n/* ---------- menu surface ---------- */\n.aun-menu {\n  /* Never the dark header's colours (owner review, 2026-11-12, revision 3):\n     - light mode: the page background (--fanous-color-background) with the page's text, a clear\n       outline border and a soft shadow, so it lifts off the page and the cards; hover and the\n       current row are a light tint (the theme's menu hover half-mixed into the background);\n     - dark mode: the theme's own menu tokens, as before.\n     light-dark() follows the page's color-scheme, which every app sets per mode. */\n  --aun-menu-bg: light-dark(var(--fanous-color-background), var(--fanous-c-menu-bg));\n  --aun-menu-text: light-dark(var(--fanous-color-text-primary), var(--fanous-c-menu-text));\n  --aun-menu-muted: light-dark(var(--fanous-color-text-secondary), var(--fanous-c-menu-muted));\n  --aun-menu-hover: light-dark(color-mix(in srgb, var(--fanous-c-menu-hover) 50%, var(--fanous-color-background)), var(--fanous-c-menu-hover));\n  /* Separators, one rule in both modes and every app: the menu's text mixed 45% into the menu's\n     surface (light 2.47–2.73:1, dark 2.60–3.81:1 across the four themes). The theme's divider token\n     is 1.0–1.8:1 there, too faint (owner reviews: \"in dark you can't see the lines between rows\",\n     then the CMS menu, then www and profile: \"the dividers are too faint\") */\n  --aun-menu-line: light-dark(color-mix(in srgb, var(--fanous-color-text-primary) 45%, var(--fanous-color-background)), color-mix(in srgb, var(--fanous-c-menu-text) 45%, var(--fanous-c-menu-bg)));\n  /* Every row starts with one leading column (icon, app tile or avatar), so the labels line up */\n  --aun-menu-lead: 2rem;\n  --aun-menu-edge: light-dark(var(--fanous-color-outline), var(--fanous-c-menu-border));\n  position: absolute;\n  inset-inline-end: 0;\n  inset-block-start: calc(100% + var(--fanous-spacing-sm, 8px));\n  z-index: 60;\n  box-sizing: border-box;\n  /* one width for every view and app (the channel switcher no longer narrows it) */\n  width: min(21rem, calc(100vw - 2 * var(--fanous-spacing-sm, 8px)));\n  max-height: calc(100dvh - 5rem);\n  overflow-y: auto;\n  margin: 0;\n  /* rows run edge to edge (their highlight spans the menu's full width); only the ends are padded */\n  padding: 0 0 var(--fanous-spacing-xs, 4px);\n  list-style: none;\n  background: var(--aun-menu-bg);\n  color: var(--aun-menu-text);\n  border: 1px solid var(--aun-menu-edge);\n  border-radius: var(--fanous-radius-md, 8px);\n  box-shadow: var(--fanous-elevation-medium);\n  font-size: 0.9375rem;\n  font-weight: 400;\n  line-height: 1.35;\n  text-align: start;\n}\n.aun-menu[hidden] {\n  display: none;\n}\n.aun-menu ul {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.aun-menu li {\n  margin: 0;\n}\n/* phone: a sheet under the header, the full width less a small gutter */\n@media (max-width: 30rem) {\n  .aun-menu {\n    position: fixed;\n    inset-inline: var(--fanous-spacing-sm, 8px);\n    inset-block-start: calc(var(--aun-header-height, 3.5rem) + var(--fanous-spacing-xs, 4px));\n    width: auto;\n    max-height: calc(100dvh - var(--aun-header-height, 3.5rem) - var(--fanous-spacing-lg, 16px));\n  }\n}\n\n/* who is signed in: the current account, a tinted panel across the menu's full width at the top\n   (.aun-menu scope: it outranks .aun-menu-item when the panel is also a link to the profile) */\n.aun-menu .aun-menu-who {\n  display: flex;\n  align-items: center;\n  gap: var(--fanous-spacing-md, 12px);\n  box-sizing: border-box;\n  width: 100%;\n  min-height: 4.25rem;\n  margin: 0;\n  padding: var(--fanous-spacing-md, 12px) var(--fanous-spacing-lg, 16px);\n  border-radius: calc(var(--fanous-radius-md, 8px) - 1px) calc(var(--fanous-radius-md, 8px) - 1px) 0 0;\n  background: var(--aun-menu-hover);\n  color: var(--aun-menu-text);\n}\n.aun-menu .aun-menu-who .aun-avatar {\n  width: 2.5rem;\n  height: 2.5rem;\n  font-size: 1rem;\n}\n.aun-menu-who-text {\n  display: flex;\n  flex: 1 1 auto;\n  flex-direction: column;\n  gap: 1px;\n  min-width: 0;\n}\n.aun-menu-who-name {\n  font-size: 1rem;\n  font-weight: 600;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* An email that does not fit keeps its domain: the local part shrinks with an ellipsis, the\n   \"@domain\" stays whole (markup: .aun-email > .aun-email-local + .aun-email-domain, full address\n   in title) */\n.aun-email {\n  display: flex;\n  min-width: 0;\n  max-width: 100%;\n  unicode-bidi: isolate;\n  direction: ltr;\n}\n[dir='rtl'] .aun-email {\n  justify-content: flex-end;\n}\n.aun-email-local {\n  min-width: 1.5em;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.aun-email-domain {\n  flex: none;\n  max-width: 75%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.aun-menu-who-sub,\n.aun-acct-email,\n.aun-acct-current {\n  color: var(--aun-menu-muted);\n  font-size: 0.8125rem;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* section header: names the group under it (never upper-cased or letter-spaced: Arabic) */\n.aun-menu-label {\n  display: block;\n  margin: 0;\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-lg, 16px) var(--fanous-spacing-xs, 4px);\n  color: var(--aun-menu-muted);\n  font-size: 0.75rem;\n  font-weight: 700;\n  line-height: 1.3;\n  letter-spacing: 0;\n  text-transform: none;\n}\n\n/* separator: full width, the same space above and below */\n.aun-menu-sep {\n  height: 0;\n  margin: var(--fanous-spacing-xs, 4px) 0;\n  padding: 0;\n  border: 0;\n  border-block-start: 1px solid var(--aun-menu-line);\n}\n.aun-menu-who + .aun-menu-sep,\n.aun-menu :where(li, div):has(.aun-menu-who) + .aun-menu-sep {\n  margin-block-start: 0;\n}\n\n/* item: a link or a button */\n.aun-menu-item {\n  display: flex;\n  align-items: center;\n  gap: var(--fanous-spacing-md, 12px);\n  box-sizing: border-box;\n  width: 100%;\n  min-height: 2.75rem;\n  margin: 0;\n  padding: var(--fanous-spacing-xs, 4px) var(--fanous-spacing-lg, 16px);\n  border: 0;\n  border-radius: 0;\n  background: transparent;\n  color: var(--aun-menu-text);\n  font: inherit;\n  text-align: start;\n  text-decoration: none;\n  cursor: pointer;\n}\n.aun-menu-item:hover,\n.aun-menu-item:focus-visible {\n  background: var(--aun-menu-hover);\n  color: var(--aun-menu-text);\n  text-decoration: none;\n}\n.aun-menu-item:focus-visible,\n.aun-acct-signout:focus-visible {\n  outline: 2px solid var(--fanous-color-focus-ring);\n  outline-offset: -2px;\n}\n.aun-menu-item:active {\n  background: var(--aun-menu-hover);\n}\n.aun-menu-item[disabled],\n.aun-menu-item[aria-disabled='true'] {\n  cursor: progress;\n  opacity: 0.6;\n}\n/* the current account and a context line are not actions: no busy look */\n.aun-menu-item[disabled][aria-current='true'],\n.aun-menu-item[aria-disabled='true'].aun-menu-who-sub {\n  cursor: default;\n  opacity: 1;\n}\n/* leading icons sit centred in the leading column; trailing ones (a chevron) at the end */\n.aun-menu-item > svg,\n.aun-menu-icon {\n  width: 1.25rem;\n  height: 1.25rem;\n  flex: none;\n  margin-inline: calc((var(--aun-menu-lead) - 1.25rem) / 2);\n  color: var(--aun-menu-muted);\n}\n.aun-menu-item > .aun-menu-text ~ svg {\n  margin-inline: auto 0;\n}\n.aun-menu-item > .aun-avatar {\n  width: var(--aun-menu-lead);\n  height: var(--aun-menu-lead);\n}\n.aun-menu-item > .aun-menu-text {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* the current page / app / choice */\n.aun-menu-item[aria-current]:not([aria-current='false']):not(.aun-menu-who),\n.aun-menu-item[aria-checked='true'],\n.aun-menu-item[aria-pressed='true'] {\n  background: var(--aun-menu-hover);\n  font-weight: 600;\n}\n.aun-menu-check {\n  width: 1rem;\n  height: 1rem;\n  flex: none;\n  margin-inline-start: auto;\n  color: var(--fanous-color-link);\n}\n/* sign out of every account */\n.aun-menu-item--danger,\n.aun-menu-item--danger > svg {\n  color: var(--fanous-color-error-text);\n}\n\n/* ---------- more accounts: the other accounts in this browser ---------- */\n/* One row per account, edge to edge: the switch button and its sign-out icon button highlight as\n   one row */\n.aun-acct-row {\n  display: flex;\n  align-items: center;\n  gap: 0;\n  padding-inline-end: var(--fanous-spacing-xs, 4px);\n}\n.aun-acct-row:hover,\n.aun-acct-row:focus-within {\n  background: var(--aun-menu-hover);\n}\n.aun-menu .aun-acct-row > .aun-menu-item {\n  flex: 1 1 auto;\n  min-width: 0;\n  min-height: 3.25rem;\n  padding-inline-end: var(--fanous-spacing-xs, 4px);\n  background: transparent;\n}\n.aun-menu .aun-acct-row > .aun-menu-item:focus-visible {\n  outline: 0;\n}\n.aun-acct-row:has(> .aun-menu-item:focus-visible) {\n  outline: 2px solid var(--fanous-color-focus-ring);\n  outline-offset: -2px;\n}\n.aun-acct-text {\n  display: flex;\n  flex: 1 1 auto;\n  flex-direction: column;\n  min-width: 0;\n}\n.aun-acct-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.aun-acct-row [aria-current='true'] .aun-acct-label {\n  font-weight: 600;\n}\n/* \"Sign out of {name}\": an icon button at the row's end (the name is its aria-label) */\n.aun-acct-signout {\n  display: inline-grid;\n  place-items: center;\n  flex: none;\n  width: 2.75rem;\n  height: 2.75rem;\n  margin: 0;\n  padding: 0;\n  border: 0;\n  border-radius: var(--fanous-radius-full, 999px);\n  background: transparent;\n  color: var(--aun-menu-muted);\n  font: inherit;\n  cursor: pointer;\n}\n.aun-acct-signout:hover {\n  background: color-mix(in srgb, var(--aun-menu-text) 10%, transparent);\n}\n.aun-acct-signout svg {\n  width: 1.125rem;\n  height: 1.125rem;\n}\n.aun-acct-signout:hover {\n  color: var(--fanous-color-error-text);\n}\n\n/* ---------- Al Ummah Now apps: each app's icon on its colour tile ---------- */\n/* The same icons and colours as the profile app's \"Your apps\" cards (AlUmmahNowAuth\n   apps/profile/src/launcher.ts ICON_PATHS and page.ts .app-tile-*): a white line icon on a fixed\n   gradient per app (Videos on the theme's primary). They identify the app, so they do not change\n   with the theme. The glyph is the icon's SVG as a mask, so no image is fetched. */\n.aun-app-icon {\n  position: relative;\n  display: inline-block;\n  flex: none;\n  box-sizing: border-box;\n  width: 1.75rem;\n  height: 1.75rem;\n  margin-inline: calc((var(--aun-menu-lead) - 1.75rem) / 2);\n  border-radius: 0.4375rem;\n  background: linear-gradient(135deg, var(--aun-app-from), var(--aun-app-to));\n}\n.aun-app-icon::before {\n  content: '';\n  position: absolute;\n  inset: 0.25rem;\n  background: #fff;\n  -webkit-mask: var(--aun-app-glyph) center / contain no-repeat;\n  mask: var(--aun-app-glyph) center / contain no-repeat;\n}\n/* app icons: the profile cards' icons (24px line icons, stroke 2) and colours */\n.aun-app-icon[data-app='www'] {\n  /* Website: globe */\n  --aun-app-from: #14b8a6;\n  --aun-app-to: #0f766e;\n  --aun-app-glyph: url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23000%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Ccircle cx=%2212%22 cy=%2212%22 r=%229%22/%3E%3Cpath d=%22M3 12h18M12 3c2.5 2.7 3.8 5.7 3.8 9s-1.3 6.3-3.8 9c-2.5-2.7-3.8-5.7-3.8-9S9.5 5.7 12 3z%22/%3E%3C/svg%3E');\n}\n.aun-app-icon[data-app='videos'] {\n  /* Videos: play */\n  --aun-app-from: var(--fanous-color-primary);\n  --aun-app-to: var(--fanous-color-primary-pressed, var(--fanous-color-primary));\n  --aun-app-glyph: url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23000%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Crect x=%223%22 y=%225%22 width=%2218%22 height=%2214%22 rx=%223%22/%3E%3Cpath d=%22M10 9.5v5l4.5-2.5z%22 fill=%22%23000%22/%3E%3C/svg%3E');\n}\n.aun-app-icon[data-app='profile'] {\n  /* Your profile: user */\n  --aun-app-from: #10b981;\n  --aun-app-to: #047857;\n  --aun-app-glyph: url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23000%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Ccircle cx=%2212%22 cy=%228%22 r=%224%22/%3E%3Cpath d=%22M4 21c1.5-4 4.5-6 8-6s6.5 2 8 6%22/%3E%3C/svg%3E');\n}\n.aun-app-icon[data-app='cms'] {\n  /* Content management: pencil */\n  --aun-app-from: #ef4444;\n  --aun-app-to: #b91c1c;\n  --aun-app-glyph: url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23000%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Cpath d=%22M4 20l4-1 11-11-3-3L5 16z%22/%3E%3Cpath d=%22M14 6l3 3%22/%3E%3C/svg%3E');\n}\n.aun-app-icon[data-app='admin'] {\n  /* Videos admin: shield */\n  --aun-app-from: #f59e0b;\n  --aun-app-to: #b45309;\n  --aun-app-glyph: url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23000%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Cpath d=%22M12 3l7 3v5c0 4.5-3 8.3-7 10-4-1.7-7-5.5-7-10V6z%22/%3E%3Cpath d=%22M9 12l2 2 4-4%22/%3E%3C/svg%3E');\n}\n.aun-app-icon[data-app='auth-admin'] {\n  /* Accounts admin: key */\n  --aun-app-from: #8b5cf6;\n  --aun-app-to: #5b21b6;\n  --aun-app-glyph: url('data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23000%22 stroke-width=%222%22 stroke-linecap=%22round%22 stroke-linejoin=%22round%22%3E%3Ccircle cx=%228%22 cy=%2215%22 r=%224%22/%3E%3Cpath d=%22M11 12l9-9M16 7l3 3M14 9l2 2%22/%3E%3C/svg%3E');\n}\n\n/* ---------- the context slot (NAV.md \"Slots\"): one app's own layer, e.g. the videos channel layer ---------- */\n.aun-menu-context {\n  display: flex;\n  flex-direction: column;\n}\n/* the current context (the active channel): avatar + name, like an account row */\n.aun-menu-context-current .aun-avatar {\n  width: 2rem;\n  height: 2rem;\n}\n/* a small role chip (\"Channel admin\") */\n.aun-badge {\n  flex: none;\n  margin-inline-start: auto;\n  padding: var(--fanous-spacing-xxs, 2px) var(--fanous-spacing-sm, 8px);\n  border: 1px solid var(--aun-menu-line);\n  border-radius: var(--fanous-radius-full, 999px);\n  color: var(--aun-menu-muted);\n  font-size: 0.6875rem;\n  font-weight: 600;\n  white-space: nowrap;\n}\n/* a line that explains why an action is missing (a limit reached) */\n.aun-menu-note {\n  margin: 0;\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-md, 12px);\n  color: var(--aun-menu-muted);\n  font-size: 0.8125rem;\n}\n/* an inline form (create a channel) */\n.aun-menu-form {\n  display: flex;\n  flex-direction: column;\n  gap: var(--fanous-spacing-sm, 8px);\n  padding: var(--fanous-spacing-sm, 8px) var(--fanous-spacing-md, 12px);\n}\n.aun-menu-form .aun-menu-label {\n  padding: 0;\n}\n.aun-menu-input {\n  box-sizing: border-box;\n  width: 100%;\n  min-height: 2.5rem;\n  padding: 0 var(--fanous-spacing-md, 12px);\n  border: 1px solid var(--aun-menu-line);\n  border-radius: var(--fanous-radius-sm, 4px);\n  background: transparent;\n  color: var(--aun-menu-text);\n  font: inherit;\n}\n.aun-menu-input:focus-visible {\n  outline: 2px solid var(--fanous-color-focus-ring);\n  outline-offset: -1px;\n}\n.aun-menu-form-actions {\n  display: flex;\n  gap: var(--fanous-spacing-sm, 8px);\n}\n.aun-menu-form-actions > * {\n  flex: 1 1 0;\n}\n\n/* directional icons (back, chevron, sign out) point the reading direction */\n[dir='rtl'] .aun-flip {\n  transform: scaleX(-1);\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  .aun-acct-btn,\n  .aun-icon-btn,\n  .aun-lang,\n  .aun-menu-item,\n  .aun-acct-signout {\n    transition: background-color var(--fanous-duration-fast, 120ms) ease;\n  }\n}\n";
